SELECT * FROM (SELECT CASE WHEN amount >= 1400 THEN 'high' WHEN amount >= 690 THEN 'mid' ELSE 'low' END AS amount_bucket, ROUND((100 * SUM(CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_success FROM payments WHERE amount < 770 GROUP BY CASE WHEN amount >= 1400 THEN 'high' WHEN amount >= 690 THEN 'mid' ELSE 'low' END) AS s WHERE pct_success >= 68;
